# shellcheck shell=bash
# workctl demo: database accounts. Sourced by docker-entrypoint-initdb.d (runs as the
# `mysql` user) and re-runnable as root via ../provision-users.sh (idempotent).
#
#   workctl_ro  read-only diagnostics account used by workctl (profile demo):
#               SELECT on demo.*, performance_schema.*, mysql.slow_log + PROCESS. No writes.
#   demo_app    sample service account: SELECT, INSERT, UPDATE on demo.*
#
# Passwords come from /run/secrets/mysql_{ro,app}_password (generated by up.sh). When the
# entrypoint cannot read them (secret files are mode 600 root and init runs as `mysql`),
# the accounts are created LOCKED with a throw-away password; provision-users.sh then sets
# the real passwords as root inside the container. Passwords are never printed.

_wk_secret() {
  local f="/run/secrets/$1"
  if [ -r "$f" ]; then
    tr -d '\r\n' < "$f" | sed "s/'/''/g"
  fi
  return 0
}

_wk_sql() {
  if declare -F docker_process_sql >/dev/null 2>&1; then
    docker_process_sql --database=mysql
  else
    MYSQL_PWD="$(tr -d '\r\n' < /run/secrets/mysql_root_password)" mysql -uroot --protocol=socket --database=mysql
  fi
}

_wk_ro_pw="$(_wk_secret mysql_ro_password)"
_wk_app_pw="$(_wk_secret mysql_app_password)"
_wk_lock_ro="ACCOUNT UNLOCK"
_wk_lock_app="ACCOUNT UNLOCK"
if [ -z "$_wk_ro_pw" ]; then
  _wk_ro_pw="$(head -c 32 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c 24)"
  _wk_lock_ro="ACCOUNT LOCK"
  echo "[workctl-demo] mysql_ro_password not readable by $(id -un); workctl_ro created LOCKED (run demo/environment/mysql/provision-users.sh)"
fi
if [ -z "$_wk_app_pw" ]; then
  _wk_app_pw="$(head -c 32 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c 24)"
  _wk_lock_app="ACCOUNT LOCK"
  echo "[workctl-demo] mysql_app_password not readable by $(id -un); demo_app created LOCKED (run demo/environment/mysql/provision-users.sh)"
fi

_wk_sql <<EOSQL
CREATE USER IF NOT EXISTS 'workctl_ro'@'%' IDENTIFIED BY '${_wk_ro_pw}' WITH MAX_USER_CONNECTIONS 20;
ALTER USER 'workctl_ro'@'%' IDENTIFIED BY '${_wk_ro_pw}' ${_wk_lock_ro};
GRANT SELECT ON demo.* TO 'workctl_ro'@'%';
GRANT SELECT ON performance_schema.* TO 'workctl_ro'@'%';
GRANT SELECT ON mysql.slow_log TO 'workctl_ro'@'%';
GRANT PROCESS ON *.* TO 'workctl_ro'@'%';

CREATE USER IF NOT EXISTS 'demo_app'@'%' IDENTIFIED BY '${_wk_app_pw}';
ALTER USER 'demo_app'@'%' IDENTIFIED BY '${_wk_app_pw}' ${_wk_lock_app};
GRANT SELECT, INSERT, UPDATE ON demo.* TO 'demo_app'@'%';
EOSQL

unset _wk_ro_pw _wk_app_pw _wk_lock_ro _wk_lock_app
unset -f _wk_secret _wk_sql
